#!/bin/bash
# NOMAD for Mac — default settings.
# Do not edit this file. Your personal settings live in config.local.sh
# (created by setup / the library picker) and override anything here.

NOMAD_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Where the knowledge library (ZIM files) lives.
# Point this at an external SSD in config.local.sh, e.g.:
#   LIBRARY_DIR="/Volumes/MySSD/nomad-library"
LIBRARY_DIR="$NOMAD_DIR/library"

# Local AI model (set automatically by setup.sh based on your RAM).
NOMAD_MODEL="qwen3:8b"

# Ports (change only if something else on your Mac uses them).
KIWIX_PORT=8090   # the raw library browser
APP_PORT=8900     # the NOMAD dashboard + chat

# Load personal overrides.
[ -f "$NOMAD_DIR/config.local.sh" ] && source "$NOMAD_DIR/config.local.sh"

export NOMAD_DIR LIBRARY_DIR NOMAD_MODEL KIWIX_PORT APP_PORT
